import { Directory, File, Paths } from "expo-file-system";

/**
 * Device-only storage for sealed vault files (native: `<documents>/vault-files/`).
 * Holds ciphertext only (see `vault-files.ts`); never backed up, never synced.
 * Metro resolves `vault-file-store.web.ts` (IndexedDB) on web.
 */
const DIR_NAME = "vault-files";
/** File ids are generated by the app (`createId`); anything else is refused. */
const NAME_RE = /^[\w-]{1,80}$/;

function dir(): Directory {
  return new Directory(Paths.document, DIR_NAME);
}

function fileFor(name: string): File {
  if (!NAME_RE.test(name)) throw new Error("vault-file-name");
  return new File(dir(), `${name}.bin`);
}

export async function putFile(name: string, bytes: Uint8Array): Promise<void> {
  const folder = dir();
  if (!folder.exists) folder.create({ intermediates: true, idempotent: true });
  const file = fileFor(name);
  if (!file.exists) file.create({ overwrite: true });
  file.write(bytes);
}

export async function getFile(name: string): Promise<Uint8Array | null> {
  const file = fileFor(name);
  if (!file.exists) return null;
  return await file.bytes();
}

export async function deleteFile(name: string): Promise<void> {
  const file = fileFor(name);
  if (file.exists) file.delete();
}

export async function listFiles(): Promise<string[]> {
  const folder = dir();
  if (!folder.exists) return [];
  return folder
    .list()
    .filter((entry): entry is File => entry instanceof File && entry.name.endsWith(".bin"))
    .map((entry) => entry.name.slice(0, -".bin".length));
}

export async function wipeFiles(): Promise<void> {
  const folder = dir();
  if (folder.exists) folder.delete();
}
